interface TelemetryMessage {
  node_id: string;
  tx_id: string;
  tx_time_ms: number;
  pow_time_ms: number;
}

interface NodeStatusMessage {
  type: 'node_status';
  payload: {
    online_nodes: string[];
    offline_nodes: string[];
  };
}

struct tx_data {
    std::string transaction_id;       // Unique ID
    std::string sender;               // Sender node UID
    std::string receiver;             // Receiver node UID
    double amount;                    // Energy units
    std::string unit;                 // Unit type (e.g., kWh)
    double price_per_unit;            // Tariff rate
    std::string currency;             // Currency code
    int64_t timestamp;                // Creation timestamp
    std::vector<std::string> parents; // Parent transaction refs
};

struct tx_metadata {
    int64_t lastUpdated;               // Last modification
    std::unordered_set<std::string> weightMap;
    int cumulative_weight;             // Total approvals
    std::string signature1;            // Sender signature
    std::string signature2;            // Receiver signature
    std::string checksum;              // Integrity hash
    int64_t consensusTimestamp;        // When consensus reached
    std::vector<std::pair<int64_t, std::string>> hops;
};

const orderSchema = new Schema({
  userId: { type: Schema.Types.ObjectId, ref: 'User' },
  status: {
    type: String,
    enum: ['pending', 'paid', 'processing', 'shipped', 'delivered', 'cancelled'],
    default: 'pending'
  },
  items: [{
    productId: { type: Schema.Types.ObjectId, ref: 'Product' },
    variantId: String,
    quantity: Number,
    price: Number,  // Snapshot at purchase
    name: String
  }],
  shipping: {
    address: {
      street: String,
      city: String,
      state: String,
      zip: String,
      country: String
    },
    method: String,
    cost: Number,
    estimatedDelivery: Date
  },
  payment: {
    stripePaymentIntentId: String,
    amount: Number,
    currency: { type: String, default: 'USD' },
    status: String
  },
  totals: {
    subtotal: Number,
    shipping: Number,
    tax: Number,
    discount: Number,
    total: Number
  },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now }
});
